  function setPanel(name){if(name==='staff'){openOffice();return;}if(!['stock','market','contracts','development','staff'].includes(name))return;panel=name;document.querySelectorAll('[data-tab]').forEach(b=>{const selected=b.dataset.tab===name;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});$('business-panel').setAttribute('aria-labelledby','tab-'+name);renderPanel(true);}
