  function setHallArea(next,id=selectedBin){if(!['foundry','warehouse','washer','cnc'].includes(next))return;area=next;selectedBin=id;hover=-1;warehouseKey='';$('production-inspector').hidden=area!=='foundry';$('warehouse-inspector').hidden=area!=='warehouse';$('washer-inspector').hidden=area!=='washer';$('cnc-inspector').hidden=area!=='cnc';$('hall-title').textContent={foundry:'Tvoja zlievareň.',warehouse:'Sklad a príjem surovín.',washer:'Pieskovač.',cnc:'CNC hala.'}[area];$('hall-label').textContent={foundry:'HALA 01 / ODSTREDIVÉ ODLIEVANIE',warehouse:'HALA 02 / ZÁSOBY A EXPEDÍCIA',washer:'HALA 03 / ČISTENIE RÚR VODOU',cnc:'HALA 04 / REZANIE RÚR NA KRÚŽKY'}[area];$('area-switch-label').textContent=area==='foundry'?'TAVIAREŇ → SKLAD':area==='warehouse'?'SKLAD → PIESKOVAČ':area==='washer'?'PIESKOVAČ → CNC':'CNC → KANCELÁRIA';$('area-switch').setAttribute('aria-label',area==='foundry'?'Prejsť do skladu':area==='warehouse'?'Prejsť do pieskovača':area==='washer'?'Prejsť do CNC haly':'Prejsť do Kancelárie');document.querySelectorAll('[data-area]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.area===area)));document.querySelector('.scene-bottom').innerHTML=area==='cnc'?'<span><i class="cnc-led on"></i>Zapnuté</span><span><i class="cnc-led"></i>Vypnuté</span><span class="scale-note">VIZUÁLNY NÁHĽAD</span>':area==='washer'?'<span><i class="legend water"></i>Vodné čistenie</span><span><i class="legend ready"></i>Opracovaný výrobok</span><span class="scale-note">TOK MATERIÁLU ←</span>':area==='warehouse'?'<span><i class="legend hot"></i>Príjem</span><span><i class="legend ready"></i>Uskladnené</span>':'<span><i class="legend hot"></i>Odlievanie</span><span><i class="legend water"></i>Chladenie</span><span><i class="legend ready"></i>Hotovo</span><span class="scale-note">1 deň = 3 minúty</span>';canvas.setAttribute('aria-label',area==='cnc'?'CNC hala: 1 až 4 hore, AMADA vľavo dole, 5 a 6 vpravo dole. Kliknutie prepína signalizáciu.':area==='washer'?'Hala Pieskovač. Modrý uzavretý stroj, vstup rúr sprava a výstup čistých rúr vľavo.':area==='warehouse'?'Sklad. Klikni na zásobník.':'Výrobná hala. Klikni na odstredivku.');document.querySelector('.control-panel').setAttribute('aria-label',area==='cnc'?'Vizuálne ovládanie CNC':area==='washer'?'Ovládanie pieskovača':area==='warehouse'?'Ovládanie skladov':'Ovládanie odstrediviek');renderUI(true);}
