  function renderCnc(){cncButtons.forEach((b,i)=>{const name=i===6?'AMADA':'CNC '+(i+1),owned=state.cncOwned[i],on=state.cncPower[i];b.disabled=paused||i===6||!owned&&state.money<F.cncPrice(i);b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',name+' – '+(i===6?'zamknutá':!owned?'kúpiť za '+F.cncPrice(i)+' ₵':on?'vypnúť':'zapnúť'));b.innerHTML='<i class="cnc-led'+(on?' on':'')+'"></i><span><strong>'+name+'</strong><small>'+(i===6?'Odomknutie pripravujeme':owned?'Kúpený · rezanie zatiaľ neaktívne':'Stroj ešte nevlastníš')+'</small></span><b>'+(i===6?'Zamknutá':!owned?F.cncPrice(i)+' ₵':on?'Zapnuté':'Vypnuté')+'</b>';});if(area==='cnc'){$('count').textContent=state.cncOwned.filter(Boolean).length+' / 6 kúpených';$('production-state').textContent='CNC · VÝROBA ZATIAĽ NEAKTÍVNA';$('crew-badge').textContent='AMADA ZAMKNUTÁ';}}
  $('wash-start').addEventListener('click',()=>execute({type:'washer',action:'start'}));$('wash-product').addEventListener('change',e=>execute({type:'washer',action:'configure',product:e.target.value}));$('wash-auto').addEventListener('change',e=>execute({type:'washer',action:'auto',enabled:e.target.checked}));$('wash-market').addEventListener('click',()=>openMarket('goods:'+F.WASH.outputs[state.washer.product]));
  function renderWasher(){if(area!=='washer')return;const w=state.washer,stage=F.washStage(state),output=F.WASH.outputs[w.product],reason=F.canWash(state);$('washer-state').textContent=w.active&&!F.washerRunning(state)?'Pozastavené · chýba obsluha alebo mzdy':{idle:'Pripravený na výrobok',loading:'Nakladanie sprava',washing:'Vodné čistenie v komore',ejecting:'Vysúvanie očisteného výrobku'}[stage];$('washer-state').classList.toggle('washing',stage==='washing'&&F.washerRunning(state));$('wash-progress').value=w.elapsed;$('wash-product').value=w.product;$('wash-product').disabled=paused||!!w.active;$('wash-input').textContent=F.available(state,w.product)+' ks';$('wash-output').textContent=state.goods[output]+' ks';$('wash-time').textContent=(w.active?Math.ceil(F.WASH.total-w.elapsed):F.WASH.total)+' s';$('wash-time-label').textContent=w.active?'Zostáva':'Cyklus';$('wash-price').textContent=F.quote(state,'goods:'+output).bid+' ₵';$('wash-auto').checked=w.auto;$('wash-auto').disabled=paused;$('wash-start').disabled=paused||!!reason;$('wash-start').textContent=w.active?'Prebieha čistenie':'Naložiť a vyčistiť · 6 ₵';$('wash-hint').textContent=w.active&&!F.washerRunning(state)?'Rozpracovaný kus čaká na obsluhu pieskovača alebo doplatenie miezd. Ďalší materiál ani platba sa neodoberá.':w.active?'Čistenie prebieha aj pri prechode do inej haly. Výstup sa automaticky uloží do skladu.':reason||'Výrobok sa odoberie zo skladu. Vyčistený kus sa vráti ako samostatný výrobok.';$('wash-total').textContent=w.cleaned;document.querySelectorAll('.wash-flow span').forEach((el,i)=>el.classList.toggle('active',['loading','washing','ejecting'][i]===stage));}
