  $('pause').addEventListener('click',()=>setPause(!paused));$('resume').addEventListener('click',()=>setPause(false));$('news').addEventListener('click',()=>$('news-dialog').showModal());$('close-news').addEventListener('click',()=>$('news-dialog').close());$('help').addEventListener('click',()=>$('help-dialog').showModal());$('close-help').addEventListener('click',()=>$('help-dialog').close());$('start-playing').addEventListener('click',()=>$('help-dialog').close());
  $('new-game').addEventListener('click',()=>$('reset-dialog').showModal());$('cancel-reset').addEventListener('click',()=>$('reset-dialog').close());$('confirm-reset').addEventListener('click',()=>{state=F.fresh();panelKey='';setArea('foundry');setPause(false);$('reset-dialog').close();setPanel('stock');save();toast('Nová dielňa. V sklade je 60 kg železa a 20 kg zinku. Prijmi tím v Kancelárii.');});
