    $('stock-badge').textContent=F.used(state,'goods')+' ks';$('contract-badge').textContent=state.contracts.filter(c=>['active','offer'].includes(c.status)).length;$('market-ticker').textContent=F.event(state).title+' · nové ceny o '+Math.max(1,Math.ceil(F.quote(state,tradeItem).next))+' s';
