    const t=F.temperature(m),hasMetal=failed||ready||unloading||working&&m.elapsed>F.FLOW.carryEnd;$('temperature').innerHTML=(hasMetal?fmt(t):'—')+' <small>°C</small>';$('temperature').style.color=stage==='cooling'?'#a9e6fb':(failed||working)&&hasMetal?'#ffd093':ready?'#c2dfa8':'#e3eee7';$('heat-fill').style.width=(hasMetal?(t-20)/(p.temp-20)*100:0)+'%';
