    $('bin-detail').innerHTML='<div class="bin-symbol" style="color:'+p.color+'">'+({iron:'Fe',steel:'OC',copper:'Cu',tin:'Sn',zinc:'Zn'}[id])+'<small>ÚROVEŇ '+(state.bins[id]+1)+'</small></div><h3>'+p.name+'</h3><div class="bin-amount">'+count+' <small>/ '+max+' kg</small></div><progress max="'+max+'" value="'+count+'" aria-label="Naplnenie zásobníka"></progress><div class="cycle-row"><span>Na príjmovej rampe</span><strong>'+pending+' kg</strong></div><div class="cycle-row"><span>Voľná kapacita</span><strong>'+Math.max(0,max-count)+' kg</strong></div><button class="primary" data-store="'+id+'"'+(paused||amount<1?' disabled':'')+'>Uskladniť '+Math.max(0,amount)+' kg</button><p class="warehouse-intro">'+(pending&&amount<pending?'Zvyšných '+(pending-amount)+' kg zostane na rampe. Rozšír zásobník.':pending?'Uložený materiál bude ihneď dostupný pre výrobu.':'Nové suroviny objednaj na burze.')+'</p><button class="outline" data-expand-bin="'+id+'"'+(paused||state.bins[id]>=8||state.money<cost+50?' disabled':'')+'>'+(state.bins[id]>=8?'Maximálna kapacita':'Zväčšiť na '+(max+F.BIN_BASE[id])+' kg · '+cost+' ₵')+'</button><button class="outline" data-buy-raw="'+id+'">Nakúpiť '+p.short.toLowerCase()+' →</button>';
