  function updateOfficeNumbers(){const left=Math.max(0,Math.ceil(F.nextPay(state)-state.clock));document.querySelectorAll('[data-office-pay]').forEach(e=>e.textContent=Math.floor(left/60)+' min '+left%60+' s');document.querySelectorAll('[data-office-accrued]').forEach(e=>e.textContent=cash(state.payroll.accrued));}
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.office!==undefined){openOffice(d.position);return;}if(d.officeTab){officeTab=d.officeTab;renderOffice(true);return;}if(d.recruit){officePosition=d.recruit;officeTab='hire';renderOffice(true);return;}if(d.hire)execute({type:'personnel',action:'hire',position:d.position,candidateId:d.hire});if(d.cover)execute({type:'personnel',action:'overtime',position:d.position,employeeId:d.cover});if(d.officePayDebt!==undefined)execute({type:'payWages'});if(d.dismiss){const person=F.employee(state,d.dismiss);dismissId=person.id;$('dismiss-copy').textContent=person.name+' · '+Math.floor((state.clock-person.hiredAt)/F.DAY)+' dní zamestnania. Odstupné '+cash(F.severance(state,person))+' sa pripočíta k najbližšej týždennej výplate. Už zarobená mzda zostane zachovaná.';$('dismiss-dialog').showModal();}});
  $('office-room').addEventListener('change',e=>{if(e.target.id==='office-position'){officePosition=e.target.value;renderOffice(true);}});
